passing arguments to another screen while using named routes<p>so i'm making a basic bmi calculator app</p>
<p>this is bmiBrain.dart</p>
<pre><code>class BmiBrain{



final int weight;
  final int height;

  double _bmi;

  BmiBrain({this.height, this.weight});

  String bmiCalculator(){
    _bmi = weight / pow(height, 2);
    return _bmi.toStringAsFixed(1);
  }

  String getWeightStatus(){
    if(_bmi &gt;= 25.0){
      return &quot;OVERWEIGHT&quot;;
    } else if (_bmi &gt; 18.5){
      return &quot;NORMAL&quot;;
    } else {
      return &quot;UNDERWEIGHT&quot;;
    }

  }

  String getDiagnostic(){
    if(_bmi &gt;= 25.0){
      return &quot;Your body height is too high&quot;;
    } else if (_bmi &gt; 18.5){
      return &quot;Your body weight is normal, Noice&quot;;
    } else {
      return &quot;You are so poor you don't eat enough lol&quot;;
    }

  }
</code></pre>
