      );

  Map&lt;String, dynamic&gt; toJson() =&gt; {
        &quot;id&quot;: id == null ? null : id,
        &quot;num&quot;: num == null ? null : num,
        &quot;name&quot;: name == null ? null : name,
        &quot;img&quot;: img == null ? null : img,
        &quot;type&quot;: type == null ? null : List&lt;dynamic&gt;.from(type.map((x) =&gt; x)),
        &quot;height&quot;: height == null ? null : height,
