how to show full results for X in double (for e.g X=3.45)?<p>I had made this code to resolve an equation which X is unknown (Ax + B = 0) it's working fine; but cannot show full results for X in double (for e.g X=3.45) value how can I do it thank you for your help</p>
<pre><code>import 'dart:io' show stdin;
import 'dart:core' show FormatException, num, print;
import 'dart:math' show Random;

void main() {
for(var i=0 ; i&lt;1 ; i--) {
  try {
    print(&quot;Equation N° 1 : ax+b=0&quot;);
    print(&quot;Enter value of A&quot;);
    var a = stdin.readLineSync();
    var A = num.parse(a!);
    print(&quot;Enter value of B&quot;);
    var b = stdin.readLineSync();
    var B = num.parse(b!);
    var X;
    if (B != 0) {
      if (A != 0) {
        print(&quot;A = $A&quot;);
        print(&quot;B = $B&quot;);
        X = -B ~/ A;
        print(&quot;X=$X&quot;);
      } else if (A == 0) {
        print(A);
        print(B);
        print(&quot;The equation, does not admit a solution.&quot;);
        print(&quot;X = No solution &quot;);
      }
    } else {
      if (A != 0) {
        print(A);
        print(B);
        print(&quot;the equation, admit 0 for solution&quot;);
        print(&quot;X = 0&quot;);
      } else {
        print(A);
        print(B);
        print(&quot;the equation, admits an infinity of solutions&quot;);
        print(&quot;X = +∞&quot;);
      }
    }
  }
  on FormatException {
    print(&quot;Invalid Value&quot;);
    print(&quot;Please Entre a Valid Value&quot;);
  }
}
  }
