class LocationDataFinal {
  LocationDataFinal({
    required this.batchcomplete,
    required this.query,
  });

  String batchcomplete;
  Query query;

  factory LocationDataFinal.fromJson(Map&lt;String, dynamic&gt; json) =&gt;
      LocationDataFinal(
        batchcomplete: json[&quot;batchcomplete&quot;],
        query: Query.fromJson(json[&quot;query&quot;]),
      );
}

class Query {
  Query({
    required this.pages,
  });

  Map&lt;String, Page&gt; pages;

  factory Query.fromJson(Map&lt;String, dynamic&gt; json) =&gt; Query(
        pages: Map.from(json[&quot;pages&quot;])
            .map((k, v) =&gt; MapEntry&lt;String, Page&gt;(k, Page.fromJson(v))),
      );
}

class Page {
  Page({
    required this.pageid,
    required this.ns,
    required this.title,
    required this.index,
    required this.coordinates,
    required this.original,
    required this.description,
    required this.descriptionsource,
    required this.extract,
  });

  int pageid;
  int ns;
  String title;
  int index;
  List&lt;Coordinate&gt; coordinates;
  Original original;
  String description;
  String descriptionsource;
  String extract;

  factory Page.fromJson(Map&lt;String, dynamic&gt; json) =&gt; Page(
        pageid: json[&quot;pageid&quot;],
        ns: json[&quot;ns&quot;],
        title: json[&quot;title&quot;],
        index: json[&quot;index&quot;],
        coordinates: List&lt;Coordinate&gt;.from(
            json[&quot;coordinates&quot;].map((x) =&gt; Coordinate.fromJson(x))),
        original: json[&quot;original&quot;] == null
            ? Original(
                source:
                    &quot;https://tigres.com.tr/wp-content/uploads/2016/11/orionthemes-placeholder-image-1.png&quot;,
                width: 300,
                height: 200)
            : Original.fromJson(json[&quot;original&quot;]),
        description: json[&quot;description&quot;] == null ? &quot;asd&quot; : json[&quot;description&quot;],
        descriptionsource:
            json[&quot;descriptionsource&quot;] == null ? &quot; &quot; : json[&quot;descriptionsource&quot;],
        extract: json[&quot;extract&quot;],
      );
}

class Coordinate {
  Coordinate({
    required this.lat,
    required this.lon,
    required this.primary,
    required this.globe,
  });

  double lat;
  double lon;
  String primary;
  Globe globe;

  factory Coordinate.fromJson(Map&lt;String, dynamic&gt; json) =&gt; Coordinate(
        lat: json[&quot;lat&quot;].toDouble(),
        lon: json[&quot;lon&quot;].toDouble(),
        primary: json[&quot;primary&quot;],
        globe: globeValues.map[json[&quot;globe&quot;]]!,
      );
}

enum Globe { EARTH }

final globeValues = EnumValues({&quot;earth&quot;: Globe.EARTH});

class Original {
  Original({
    required this.source,
    required this.width,
    required this.height,
  });

  String source;
  int width;
  int height;

  factory Original.fromJson(Map&lt;String, dynamic&gt; json) =&gt; Original(
        source: json[&quot;source&quot;],
        width: json[&quot;width&quot;],
        height: json[&quot;height&quot;],
      );
}

class EnumValues&lt;T&gt; {
  late Map&lt;String, T&gt; map;
  late Map&lt;T, String&gt; reverseMap;

  EnumValues(this.map);
}

