      await startDecompressing();
    } catch (err) {}

    // == i) Stage i, etc.
</code></pre>
<p>But something does not work in my download stage as it starts stage 2) prior stage 1) completion.</p>
<p>My stage one (download) is like so:</p>
<pre><code>  /// Starts download procress
  Future&lt;void&gt; startDownloading() async {
    print(&quot;startDownloading…&quot;);

    _state = DownloadState.downloading;
    _progress = 0;
    notifyListeners();

    /// Database string url
    final databaseUrlForInstantData = &quot;https://XXX&quot;;

    try {
      final request = Request('GET', Uri.parse(databaseUrlForInstantData));

      final StreamedResponse response = await Client().send(request);

      final contentLength = response.contentLength;

      // == Start from zero
      _progress = 0;
      notifyListeners();

      /// The currently downloaded file as an array of bytes
      List&lt;int&gt; bytes = [];

      response.stream.listen(
        /// = Closure listener for newly downloaded bytes
        (List&lt;int&gt; newBytes) {
          bytes.addAll(newBytes);

          final downloadedLength = bytes.length;

          if (contentLength == null) {
            _progress = 0;
          } else {
            _progress = downloadedLength / contentLength;
          }
          notifyListeners();

          print(
              'Download in progress $_progress%: ${bytes.length} bytes so far');
        },

        /// = Download successfully completed
        onDone: () async {
          _state = DownloadState.downloaded;

          notifyListeners();

          /// The resulting local copy of the database
          final file = await _getDownloadedZipFile();

          // == Write to file
          await file.writeAsBytes(bytes);
          print('Download complete: ${bytes.length} bytes');
        },

        /// = Download error
        onError: (e) {
          _state = DownloadState.error;
          _error = e.message;
          print('Download error at $_progress%: $e');
        },
        cancelOnError: true,
      );
    }
    // == Catches potential error
    catch (e) {
      _state = DownloadState.error;
      _error = 'Could not download the databse: $e';
      print('Download error at $_progress%: $e');
    }

  }
</code></pre>,"<p>Your <code>startDownloading</code> function returns after it registers callbacks to listen to the <code>Stream</code> and does not wait for the <code>Stream</code> to complete.</p>

