                onTap: (){
                setState(() {
                1Clicked = !1Clicked;
                });
                },
                child: Container(
                decoration: BoxDecoration(
                color: 1Clicked? Colors.orange: Colors.white,
                ),
               ),
              ), 

GestureDetector(
                onTap: (){
                setState(() {
                2Clicked = !2Clicked;
                });
                },
                child: Container(
                decoration: BoxDecoration(
                color: 2Clicked? Colors.orange: Colors.white,
