class NavigationControls extends StatelessWidget {
  const NavigationControls(this._webViewControllerFuture)
      : assert(_webViewControllerFuture != null);

  final Future&lt;WebViewController&gt; _webViewControllerFuture;

  @override
  Widget build(BuildContext context) {
    return FutureBuilder&lt;WebViewController&gt;(
      future: _webViewControllerFuture,
      builder:
          (BuildContext context, AsyncSnapshot&lt;WebViewController&gt; snapshot) {
        final bool webViewReady =
            snapshot.connectionState == ConnectionState.done;
        final WebViewController controller = snapshot.data!;
        return Row(
          children: &lt;Widget&gt;[
            IconButton(
              icon: const Icon(
                Icons.arrow_back_ios,
                color: Colors.red,
              ),
              onPressed: !webViewReady
                  ? null
                  : () async {
                      if (await controller.canGoBack()) {
                        await controller.goBack();
                      } else {
                        // ignore: deprecated_member_use
                        Scaffold.of(context).showSnackBar(
                          const SnackBar(content: Text(&quot;Geçmiş Bulunamadı&quot;)),
                        );
                        return;
                      }
                    },
            ),
            IconButton(
              icon: const Icon(
                Icons.arrow_forward_ios,
                color: Colors.red,
              ),
              onPressed: !webViewReady
                  ? null
                  : () async {
                      if (await controller.canGoForward()) {
                        await controller.goForward();
                      } else {
                        // ignore: deprecated_member_use
                        Scaffold.of(context).showSnackBar(
                          const SnackBar(content: Text(&quot;Geçmiş Bulunamadı&quot;)),
                        );
                        return;
                      }
                    },
            ),
          ],
        );
      },
    );
  }
}
</code></pre>,"<p>you have provided only one <code>widget</code> as a <code>body</code>, so changing <code>_currentIndex</code> does not affect the displayed body. According to the example of this package ( in the Use with PageView and PageController section), you can use <code>PageView</code> for changing the display image! Or you can use a list of <code>widgets</code> and show the item that is related to the <code>_currentIndex</code>. so you have two solutions:</p>

