      listeTaches.add(tacheStr.toString());
    }
    print(listeTaches);
  }

  _onReorder(oldIndex, newIndex) {
    setState((){
      if(newIndex &gt; oldIndex){
        newIndex -= 1;
      }
      var item = listeTaches.removeAt(oldIndex);
      listeTaches.insert(newIndex, item);
    });
  }

  @override
