        (Timer t) =&gt; {
          fetchCompanyLiveStockData( // The function I want to run every 5 seconds
            ref,
            showNotification,
          ),
        },
      );
    } else {
      timer.cancel();
      print(&quot;Timer Canceled!&quot;);
